package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
	"unicode"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	var a string
	if scanner.Scan() {
		a = scanner.Text()
	}

	if strings.ToUpper(a) == a {
		fmt.Println(strings.ToLower(a))
	} else if len(a) > 0 && unicode.IsLower(rune(a[0])) && strings.ToUpper(a[1:]) == a[1:] {
		fmt.Println(strings.ToUpper(a[:1]) + strings.ToLower(a[1:]))
	} else {
		fmt.Println(a)
	}
}

